// @ts-check
/** @param {{ instanceId: string, state: import("./product-types.js").OfficePageState }} input @returns {string} */
export function renderHtml({ instanceId, state }) {
    const payload = JSON.stringify(state).replaceAll("<", "\\u003c").replaceAll("\u2028", "\\u2028").replaceAll("\u2029", "\\u2029");
    const panel = instanceId.replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character] ?? character);
    return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Pixel Agents · Office</title><link rel="stylesheet" href="/office.css"></head>
<body><a class="skip-link" href="#office-floor">Skip to office</a><main class="app" data-instance="${panel}">
<header class="topbar"><div class="brand"><span class="brand-mark" aria-hidden="true">✦</span><div><p class="eyebrow">A little space for big ideas</p><h1>Pixel Agents <span>Office</span></h1></div></div><div class="header-meta"><span class="read-only">Read-only dashboard</span><time id="clock"></time></div></header>
<section class="statusbar" aria-label="Source health"><div id="connection">Connecting to activity sources…</div><div class="source-actions"><button id="refresh" type="button">↻ Refresh</button><button id="codex" type="button">Enable local Codex</button></div></section>
<p id="notice" class="notice" role="status" aria-live="polite" hidden></p>
<div class="workspace"><section class="office-panel" aria-labelledby="floor-title"><header class="panel-heading"><div><p class="eyebrow">The shared floor · 01</p><h2 id="floor-title">Room to make things</h2></div><span id="occupancy" class="count">Loading office</span></header>
<div class="floor-scroll"><div id="office-floor" class="office-floor" tabindex="-1"><div class="office-wall" aria-hidden="true"><div class="pixel-window"><i></i></div><div class="wall-art">MAKE<br>GOOD<br>THINGS.</div><div class="wall-clock"></div><div class="bookshelf"><i></i><i></i><i></i><i></i><i></i></div><div class="pixel-window second"><i></i></div></div><div class="floor-sign" aria-hidden="true">✦ THE OBSERVATORY ✦</div><div id="agent-layer" class="cluster-grid"><p class="empty-state">Opening the office…</p></div><div class="common-area" aria-hidden="true"><div class="sofa"></div><div class="coffee-table"></div><div class="floor-plant"></div><span>THE LITTLE BREAK ROOM</span><div class="coffee-bar"></div></div><div id="ambience" class="ambience" aria-label="Fictional office ambience"></div></div></div>
<footer class="floor-footer"><span><span class="legend-dot working"></span> Working <span class="legend-dot waiting"></span> Waiting <span class="legend-dot idle"></span> Idle <span class="legend-dot unknown"></span> Unknown</span><span>Office decor &amp; scenes are fiction</span></footer></section>
<aside id="details" class="details panel" aria-labelledby="details-title"><p class="eyebrow">A closer look</p><h2 id="details-title">Meet the team</h2><p class="muted">Select a character or roster entry to inspect provider-reported activity and customize their local look.</p><div class="detail-empty" aria-hidden="true">✧<br>Every pixel has a place.</div></aside></div>
<div class="lower-grid"><section class="panel roster-panel" aria-labelledby="roster-title"><header class="section-heading"><div><p class="eyebrow">Provider-reported identities</p><h2 id="roster-title">The roster</h2></div><span id="roster-count" class="count">0 agents</span></header><div id="roster" class="roster"></div></section><section class="panel feed-panel" aria-labelledby="feed-title"><header class="section-heading"><div><p class="eyebrow">Facts, not office fiction</p><h2 id="feed-title">Recent activity</h2></div><span class="feed-label">Observed</span></header><ol id="feed" class="feed"><li class="muted">No observed activity yet.</li></ol></section></div>
<section class="settings panel" aria-labelledby="settings-title"><header class="section-heading"><div><p class="eyebrow">Make yourself at home</p><h2 id="settings-title">Office preferences</h2></div><span class="muted">Local presentation only</span></header><div class="preference-grid"><label class="toggle"><input id="hide-titles" type="checkbox"><span>Hide all session titles<small>Derived motifs stay visible. Titles may contain sensitive text.</small></span></label><label class="toggle"><input id="show-ended" type="checkbox"><span>Show ended agents<small>Only explicit provider end signals count as ended.</small></span></label><label class="toggle"><input id="vignettes" type="checkbox"><span>Office vignettes<small>Fictional idle scenes; never provider activity.</small></span></label><label class="toggle"><input id="dialogue" type="checkbox"><span>Character dialogue<small>Authored persona flavor, not reported thoughts.</small></span></label></div><p id="preference-status" class="muted" role="status"></p></section>
<details id="coverage" class="coverage panel"><summary>Source coverage &amp; limitations</summary><div id="coverage-content"></div><p class="muted">Provider identities are activity sources, not model or billing routes. Missing events do not prove completion. Navigation is unavailable in this read-only view.</p></details>
<footer class="page-footer"><span class="brand-tiny">✦ PIXEL AGENTS</span><span>Real signals. A fictional little office.</span><span>Keyboard: Tab to a character · Enter to inspect · Escape to return</span></footer>
<noscript><p class="notice">JavaScript is needed to display observed activity. No work is performed by this dashboard.</p></noscript>
</main><script id="office-state" type="application/json">${payload}</script><script type="module" src="/office-client.js"></script></body></html>`;
}
